    "unit": "p1_u9",
    "topic": "Mental Ability & Quantitative Aptitude",
    "question": "Pointing to a photograph, a transport officer says: 'Her mother is the only daughter of my mother.' How is the officer related to the girl in the photo (assuming officer is male)?",
