    "explanationTe": "సెండాయ్ విపత్తు తగ్గింపు ముసాయిదా (2015-2030) 7 అంతర్జాతీయ లక్ష్యాలను (Targets) మరియు 4 ప్రాధాన్యత రంగాలను నిర్దేశించింది."
