    "explanationTe": "ఏపీ పునర్వ్యవస్థీకరణ చట్టం సెక్షన్ 46(1) కింద రాయలసీమలోని 4 జిల్లాలు మరియు ఉత్తరాంధ్రలోని 3 జిల్లాలు కలిపి మొత్తం 7 వెనుకబడిన జిల్లాలకు ప్రత్యేక అభివృద్ధి ప్యాకేజీ కేటాయించబడింది."
