    "paper": 2,
    "unit": "p2_u3",
    "topic": "General",
    "question": "In Antilock Braking Systems (ABS), what electro-hydraulic cycle is executed when wheel slip exceeds threshold during sudden braking?",
    "options": [
      "Pressure Hold, Pressure Dump (Decrease), Pressure Increase",
      "Continuous Pressure Elevation",
      "Vacuum Venting only",
      "Engine Fuel Cut-off"
    ],
